def slash(color, r, w, keyline=None, cx=C, cy=C):
    """Ghostbusters-style bar, upper-left to lower-right, meeting the ring.

    `keyline` draws a shortened bar in the plate color underneath so the slash
    reads as sitting on top of the artwork instead of merging into it. It stops
    short of the ring so the slash still welds to the circle at both ends.
    """
    out = []
    if keyline:
        out.append(_bar(keyline, r - w / 2 - 2.5, w + 7, cx, cy))
    out.append(_bar(color, r, w, cx, cy))
    return "\n  ".join(out)

